/*
 * A106825  Trajectory of 1 under the morphism 1->1222, 2->2111.
 * https://oeis.org/A106825
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the n-th letter of the morphic word generated by the
 *            substitution 1 → 1222, 2 → 2111. It is obtained by starting with
 *            symbol 1 and, for each base‑4 digit of n (most significant
 *            first), replacing the current symbol by the corresponding digit
 *            of its image
 * Range:     u8 n <= 104, u16 n <= 104, u32 n <= 104, u64 n <= 104,
 *            u128 n <= 104, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    static const seq_t m1[4] = {1,2,2,2};
    static const seq_t m2[4] = {2,1,1,1};

    if (n == 0)
        return (seq_t)1;

    idx_t t = n;
    /* store base‑4 digits in reverse order */
    int d[64];
    int cnt = 0;
    while (t > 0) {
        d[cnt++] = (int)(t & 3u);
        t >>= 2;
    }

    seq_t cur = 1;
    for (int i = cnt - 1; i >= 0; --i) {
        int dig = d[i];
        cur = (cur == 1) ? m1[dig] : m2[dig];
    }
    return cur;
}
